insert into public.fonds
  (id, code, nom, categorie_produit, categorie_cifsc, gestionnaire, pourquoi, style, couverture_devises, actif_net, date_creation, rendements_composes, rendements_annuels, composition_actif)
values
  (1, '010', 'Actions nord-américaines (iA)', 'Fonds d''actions canadiennes', 'Actions principalement canadiennes', 'iA Gestion mondiale d''actifs', '—Fonds composé principalement de titres de grandes sociétés canadiennes et américaines. —Bénéficie d’une exposition d’environ 50 % aux occasions offertes par le marché américain.', '—Style : Biais de croissance avec une attention au prix —Le gestionnaire porte une attention particulière à la gestion des risques sur le plan des secteurs, des capitalisations et des principales positions dans l''indice de référence.', 'Sans couverture', '154,4 million', 'mai 1969', '{"DDA": 5.97, "3mois": 8.77, "6mois": 5.97, "1an": 17.71, "3ans": 15.37, "5ans": 13.32, "10ans": 7.29, "depuis_lancement": 5.62}'::jsonb, '{"2024": 23.35, "2023": 13.15, "2022": -10.63, "2021": 20.35, "2020": 8.74, "2019": 17.18, "2018": -10.82, "2017": 6.58, "2016": 11.42, "2015": -4.09}'::jsonb, '24,44 % Finance 17,39 % Technologies de l''information 12,22 % Industrie 8,52 % Énergie 8,25 % Matériaux 6,24 % Consommation discrétionnaire 5,93 % Biens de consommation de base 5,54 % Services de communication 3,23 % Services aux collectivités 3,21 % Santé 1,54 % Immobilier'),
  (2, '020', 'Obligations (iA)', 'Fonds de revenu', 'Revenu fixe canadien', 'iA Gestion mondiale d''actifs', '—Un portefeuille de base à revenu fixe canadien qui cherche à procurer un revenu d''intérêts et une appréciation du capital, tout en préservant le capital. —Peut bénéficier jusqu’à 30 % d’occasions en obligations étrangères, entièrement couvertes contre le risque de devise.', '—Style : Gestion active de la durée, de la répartition sectorielle et du positionnement sur la courbe de rendement, combinée à l’analyse de crédit des émetteurs corporatifs. —Investit principalement dans une combinaison d''émissions du gouvernement et d''obligations de sociétés de grande qualité.', 'Couverture active', '4 026,0 million', 'mai 1977', '{"DDA": 0.46, "3mois": -0.95, "6mois": 0.46, "1an": 4.17, "3ans": 2.55, "5ans": -2.01, "10ans": 0.19, "depuis_lancement": 1.12}'::jsonb, '{"2024": 2.56, "2023": 4.84, "2022": -13.06, "2021": -4.21, "2020": 6.85, "2019": 5.19, "2018": -0.84, "2017": 1.12, "2016": 0.45, "2015": 1.49}'::jsonb, '91,97 % Canada 6,08 % États-Unis 1,95 % Court terme et autres'),
  (3, '021', 'Obligations de sociétés canadiennes (iA)', 'Fonds de revenu', 'Revenu fixe de sociétés canadiennes', 'iA Gestion mondiale d''actifs', '—Le Fonds vise un rendement supérieur aux fonds d''obligations traditionnels au moyen d''investissements faits principalement dans des titres à revenu fixe de sociétés canadiennes de qualité. —Les obligations de sociétés ont une durée plus courte et sont généralement moins sensibles aux mouvements de taux d''intérêt que les obligations gouvernementales.', '—La stratégie s''appuie sur l''analyse détaillée des titres de sociétés, avec un accent sur la qualité du crédit et la liquidité —L''approche d''investissement combine une répartition sectorielle descendante à la sélection ascendante de titres de sociétés. —Portefeuille diversifié composé de 70 à 80 titres répartis entre plus de 40 émetteurs.', 'Couverture active', '1 806,3 million', 'mars 2016', '{"DDA": 1.17, "3mois": 0.05, "6mois": 1.17, "1an": 6.13, "3ans": 4.34, "5ans": -0.31, "10ans": 0.95}'::jsonb, '{"2024": 5.52, "2023": 6.26, "2022": -12.03, "2021": -3.36, "2020": 6.54, "2019": 6.03, "2018": -0.99, "2017": 0.79, "2016": 1.59}'::jsonb, '87,83 % Canada 10,95 % États-Unis 1,22 % Court terme et autres'),
  (4, '040', 'Diversifié (iA)', 'Fonds diversifiés', 'Équilibré canadien neutre', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à combiner la croissance du capital au revenu courant tout en minimisant les risques grâce à la diversification entre les classes d''actif et à la combinaison de différents gestionnaires ayant des styles de gestion variés. —Solution gérée canadienne reconnue pour sa simplicité et son efficacité. —Expertise d’une équipe de gestionnaires chevronnés qui se penchent quotidiennement sur les décisions de placement.', '—Approche de gestion active basée sur les décisions de l''équipe responsable de la répartition d''actif, compte tenu des prévisions économiques et du marché. —Grande latitude quant aux limites de placements (± 20 % par rapport à la répartition cible).', 'Couverture active', '2 275,2 million', 'janvier 1987', '{"DDA": 3.63, "3mois": 2.78, "6mois": 3.63, "1an": 11.55, "3ans": 8.39, "5ans": 5.7, "10ans": 3.78, "depuis_lancement": 4.41}'::jsonb, '{"2024": 12.77, "2023": 6.53, "2022": -10.03, "2021": 8.67, "2020": 6.7, "2019": 11.53, "2018": -6.2, "2017": 4.43, "2016": 4.14, "2015": 3.25}'::jsonb, '64,25 % Canada 12,90 % États-Unis 12,85 % Mondial 4,74 % International 4,48 % Court terme et autres 0,78 % Asie et Pacifique'),
  (5, '070', 'Marché monétaire (iA)', 'Fonds de revenu', 'Marché monétaire canadien', 'iA Gestion mondiale d''actifs', '—Le Fonds cherche à offrir un certain revenu d''intérêts tout en assurant la protection du capital et la liquidité. —Est conforme à un horizon d''investissement à court terme et représente un placement à faible risque.', '—Fonds investi principalement dans des titres de créance de grande qualité, dont l''échéance maximale est d''un an, garantis par les provinces, les gouvernements et certaines sociétés.', 'Couverture active', '928,7 million', 'septembre 1991', '{"DDA": 0.92, "3mois": 0.41, "6mois": 0.92, "1an": 2.44, "3ans": 2.81, "5ans": 1.72, "10ans": 1.07, "depuis_lancement": 0.79}'::jsonb, '{"2024": 3.4, "2023": 3.39, "2022": 0.79, "2021": 0.0, "2020": 0.74, "2019": 0.59, "2018": 0.54, "2017": 0.19, "2016": 0.16, "2015": 0.22}'::jsonb, '97,56 % Canada 2,31 % États-Unis 0,13 % Encaisse et équivalents'),
  (6, '081', 'Spécialisés Revenu à taux variable (Loomis Sayles)', 'Fonds de revenu', 'Prêts à taux variable', 'Loomis, Sayles & Company', '—Diversification par le biais de prêts de premier rang garantis et de titres de créance nord-américains à rendement élevé. —Protection contre les hausses de taux d''intérêt : les prêts de premier rang à taux variable ont une durée très courte (~0,25 an). —Accès à une classe d''actifs non traditionnelle pouvant être difficile à obtenir pour les investisseurs particuliers.', '—Approche d''investissement basée sur la sélection rigoureuse et ascendante des crédits. —Principalement investi dans des prêts de premier rang à taux variable, d''autres titres à taux variable et des titres de créance de sociétés nord-américaines et mondiales de qualité supérieure ou non.', 'Couverture totale', '54,2 million', 'octobre 2019', '{"DDA": -1.76, "3mois": 0.65, "6mois": -1.76, "1an": 0.73, "3ans": 2.27, "5ans": 1.52, "10ans": 1.25}'::jsonb, '{"2024": 1.53, "2023": 5.87, "2022": -4.97, "2021": 1.69, "2020": -1.26, "2019": 6.51}'::jsonb, '75,85 % États-Unis 12,25 % Court terme et autres 4,96 % Europe 4,20 % Canada 2,74 % Amérique Latine'),
  (7, '082', 'Fidelity Vision stratégique', 'Fonds d''actions américaines et internationales', 'Actions américaines', 'Fidelity Investments', '—Fonds d''actions de base flexible qui investit principalement dans des titres de capitaux propres de sociétés situées n''importe où dans le monde, en privilégiant les titres américains —Vise une valeur ajoutée du capital à long terme en investissant dans des sociétés dont la valeur estimée n''est pas pleinement reconnue par le public.', '—Style : Croissance —Portefeuille diversifié de sociétés à large capitalisation. —Vise à investir dans les meilleures sociétés qui soient, celles qui offriront une croissance des bénéfices soutenue et supérieure à la moyenne, et qui ont un modèle d''affaires solide.', 'Sans couverture', '928,1 million', 'octobre 2019', '{"DDA": 5.01, "3mois": 10.82, "6mois": 5.01, "1an": 16.99, "3ans": 26.48, "5ans": 14.66, "10ans": null, "depuis_lancement": 16.41}'::jsonb, '{"2024": 42.35, "2023": 27.89, "2022": -22.69, "2021": 19.52, "2020": 26.88, "2019": 20.06}'::jsonb, '25,14 % Technologies de l''information 21,26 % Services de communication 19,07 % Finance 9,52 % Consommation discrétionnaire 8,92 % Industrie 8,29 % Santé 1,86 % Services aux collectivités 1,68 % Biens de consommation de base 1,42 % Matériaux 0,80 % Énergie 0,08 % Immobilier'),
  (8, '084', 'Marchés émergents (Jarislowsky Fraser)', 'Fonds spécialisés', 'Actions de marchés émergents', 'Jarislowsky Fraser Limitée', '—Le Fonds vise à générer une appréciation du capital en investissant dans des sociétés situées ou exposées aux marchés émergents en croissance. —Jarislowsky Fraser possède plus de 20 ans d''expérience dans la recherche et l''investissement dans les actions internationales.', '—Fonds investi généralement dans des sociétés qui affichent des taux de croissance supérieurs, des rendements élevés sur le capital investi, des positions dominantes dans leur région et des bilans solides pour réduire le risque financier. —La gestion active limite l''exposition aux sociétés dont les modèles d''entreprise sont faibles et dont la gestion et/ou la gouvernance sont médiocres, ainsi qu''aux pays dont les fondamentaux sont douteux.', 'Couverture active', '44,0 million', 'octobre 2019', '{"DDA": 6.08, "3mois": 3.8, "6mois": 6.08, "1an": 12.78, "3ans": 7.16, "5ans": 2.45, "10ans": null, "depuis_lancement": 1.64}'::jsonb, '{"2024": 14.12, "2023": -2.99, "2022": -16.59, "2021": -8.57, "2020": 16.72, "2019": 12.2}'::jsonb, NULL),
  (9, '085', 'Infrastructures mondiales (Dynamique)', 'Fonds spécialisés', 'Actions d’infrastructures mondiales', 'Fonds Dynamique', '—Fonds investi dans un portefeuille diversifié de sociétés du monde entier, cotées en bourse, qui possèdent directement des actifs d''infrastructure. —Les investissements dans les infrastructures sont attrayants pour leur faible corrélation avec les actions et les obligations ce qui permet de diversifier le portefeuille à long terme.', '—Le Fonds utilise une approche ascendante, axée sur la qualité à un prix raisonnable. —Le gestionnaire recherche des sociétés dotées des meilleures équipes de direction, des sociétés dominantes dans leur secteur, et ayant un historique de flux de trésorerie croissants et de bilans solides. —Diversification par secteur d''activité, par zone géographique et par type d''infrastructure.', 'Couverture active', '114,3 million', 'octobre 2019', '{"DDA": 9.17, "3mois": 5.46, "6mois": 9.17, "1an": 22.13, "3ans": 6.74, "5ans": 6.88, "10ans": 6.22}'::jsonb, '{"2024": 12.45, "2023": -2.04, "2022": -3.46, "2021": 7.12, "2020": -1.56, "2019": 23.41}'::jsonb, NULL),
  (10, '134', 'Actions mondiales de dividendes (iA)', 'Fonds d''actions américaines et internationales', 'Actions mondiales', 'iA Gestion mondiale d''actifs', '—Vise à investir dans des sociétés mondiales de qualité élevée versant des dividendes et ayant la capacité de les augmenter au fil du temps pour créer un effet composé. —Au moins 90 % des sociétés du Fonds versent des dividendes.', '—Style : Qualité et croissance des dividendes —Sélection visant à identifier les actions de sociétés de qualité ayant un excellent modèle d’affaires et une équipe de direction respectueuse des actionnaires.', 'Sans couverture, mais peut couvrir de façon opportuniste', '202,5 million', 'octobre 2023', '{"DDA": 0.33, "3mois": 0.42, "6mois": 0.33, "1an": 10.8, "3ans": null, "5ans": null, "10ans": null, "depuis_lancement": 16.11}'::jsonb, '{"2024": 23.52, "2023": null, "2022": null, "2021": null, "2020": null, "2019": null, "2018": null, "2017": null, "2016": null, "2015": null}'::jsonb, '18,93 % Finance 17,40 % Technologies de l''information 12,96 % Industrie 11,21 % Consommation discrétionnaire 9,11 % Santé 8,30 % Matériaux 7,90 % Services de communication 6,23 % Énergie 4,01 % Biens de consommation de base 3,58 % Services aux collectivités'),
  (11, '154', 'Opportunités mondiales (Loomis Sayles)', 'Fonds d''actions américaines et internationales', 'Actions mondiales', 'Loomis, Sayles & Company', '—Fonds investi principalement dans un portefeuille diversifié de titres de capitaux propres de sociétés à travers le monde. —Offre une stratégie sans contrainte d’actions mondiales cherchant à investir dans de multiples secteurs, régions et pays aux fins d’atteindre un potentiel de rendement total élevé.', '—Le procédé de placement discipliné et collaboratif, soutenu par la plateforme de recherche mondiale approfondie de Loomis Sayles, assure que seules leurs meilleures idées sont représentées dans le Fonds. —Un portefeuille à forte conviction généralement composé de 35 à 65 titres de sociétés de qualité que les gestionnaires de portefeuille perçoivent comme étant des placements supérieurs à long terme.', 'Sans couverture', '516,6 million', 'octobre 2020', '{"DDA": -2.0, "3mois": 2.71, "6mois": -2.0, "1an": 6.3, "3ans": 18.14, "5ans": 9.64}'::jsonb, '{"2024": 26.16, "2023": 24.1, "2022": -22.92, "2021": 19.38, "2020": 14.83}'::jsonb, '29,47 % Technologies de l''information 20,18 % Finance 16,51 % Consommation discrétionnaire 16,31 % Industrie 7,11 % Santé 3,07 % Matériaux 2,93 % Services de communication 2,87 % Biens de consommation de base 0,62 % Énergie'),
  (12, '170', 'Obligations court terme (iA)', 'Fonds de revenu', 'Revenu fixe canadien à court terme', 'iA Gestion mondiale d''actifs', '—Le Fonds cherche à offrir un revenu courant et une croissance modérée du capital à long terme. —Le Fonds se caractérise par une échéance de courte à moyenne durée, ce qui permet de minimiser l''effet des fluctuations des taux d''intérêt. —Possibilité de bénéficier d''occasions d''investissement parmi des obligations étrangères et des positions hors indice.', '—Style : Gestion active —Fonds composé principalement de titres à revenu fixe canadiens à court terme de première qualité. —Processus d''investissement basé principalement sur la sélection des secteurs et des émetteurs, combiné aux anticipations de taux d''intérêt.', 'Couverture active', '393,2 million', 'décembre 1997', '{"DDA": 1.36, "3mois": 0.25, "6mois": 1.36, "1an": 4.65, "3ans": 3.02, "5ans": 0.26, "10ans": 0.38, "depuis_lancement": 0.63}'::jsonb, '{"2024": 4.39, "2023": 3.45, "2022": -5.54, "2021": -2.64, "2020": 3.86, "2019": 1.43, "2018": 0.01, "2017": -1.22, "2016": -0.52, "2015": 0.79}'::jsonb, '86,95 % Canada 8,21 % États-Unis 4,84 % Court terme et autres'),
  (13, '180', 'Indiciel américain (BlackRock)', 'Fonds d''actions américaines et internationales', 'Actions américaines', 'BlackRock', '—Le Fonds vise à reproduire le rendement de l''indice S&P 500. —Offre une exposition passive aux actions américaines.', '—BlackRock utilise une approche indicielle pour gérer le Fonds. —Fonds investi directement dans un portefeuille largement diversifié d''actions émises sur l''indice S&P 500.', 'Sans couverture', '1 431,8 million', 'janvier 1998', '{"DDA": -0.71, "3mois": 4.4, "6mois": -0.71, "1an": 11.49, "3ans": 18.42, "5ans": 13.31, "10ans": 11.33, "depuis_lancement": 12.75}'::jsonb, '{"2024": 32.36, "2023": 19.33, "2022": -14.65, "2021": 23.96, "2020": 12.98, "2019": 21.12, "2018": 1.18, "2017": 10.46, "2016": 4.86, "2015": 18.09}'::jsonb, '32,91 % Technologies de l''information 14,45 % Finance 10,32 % Consommation discrétionnaire 9,74 % Services de communication 9,25 % Santé 8,54 % Industrie 5,47 % Biens de consommation de base 2,96 % Énergie 2,38 % Services aux collectivités 2,03 % Immobilier 1,87 % Matériaux'),
  (14, '222', 'Spécialisés Fidelity Titres américains à rendement élevé - Devises neutres', 'Fonds de revenu', 'Revenu fixe à rendement élevé', 'Fidelity Investments', '—Fonds investi principalement dans des titres à revenu fixe qui privilégie les titres à revenu fixe à rendement élevé et de qualité inférieure, les actions privilégiées et les titres convertibles émis par des sociétés américaines. —Le Fonds vise à couvrir l''exposition aux devises étrangères et offre ainsi l''accès au potentiel des titres à rendement élevé du marché américain, sans l''exposition au risque de devises.', '—Style : Analyse de crédit et prévision des taux d’intérêt —Accent mis sur les données fondamentales des sociétés, particulièrement sur une structure de capital solide ainsi que la capacité à produire des flux de trésorerie.', 'Couverture totale', '147,1 million', 'juin 2015', '{"DDA": 3.1, "3mois": 3.14, "6mois": 3.1, "1an": 7.34, "3ans": 6.96, "5ans": 4.19, "10ans": 2.54, "depuis_lancement": 2.5}'::jsonb, '{"2024": 5.58, "2023": 9.32, "2022": -10.56, "2021": 5.99, "2020": -0.45, "2019": 11.36, "2018": -5.4, "2017": 5.14, "2016": 10.19, "2015": -4.29}'::jsonb, 'Caractéristiques du portefeuille Qualité moyenne des obligations BB Rendement à l''échéance 7,6 % Coupon moyen n.d. Durée modifiée 2,8 années Échéance moyenne 9,6 années'),
  (15, '233', 'Innovation thématique (iA)', 'Fonds d''actions américaines et internationales', 'Actions américaines', 'iA Gestion mondiale d''actifs', '—Fonds investi principalement dans des sociétés américaines novatrices à grande capitalisation qui cherchent à tirer avantage des progrès technologiques et/ou de prospérer dans un contexte en perpétuel changement.', '—Un procédé de placement discipliné qui combine une analyse qualitative et quantitative en insistant sur la gestion des risques. —Portefeuille bien diversifié qui cherche à investir largement dans divers secteurs de l''économie.', 'Sans couverture', '1 377,7 million', 'mars 2016', '{"DDA": 1.27, "3mois": 8.95, "6mois": 1.27, "1an": 12.66, "3ans": 20.51, "5ans": 13.28, "10ans": null, "depuis_lancement": 12.39}'::jsonb, '{"2024": 36.73, "2023": 22.04, "2022": -21.16, "2021": 18.35, "2020": 29.9, "2019": 19.2, "2018": 1.86}'::jsonb, '37,84 % Technologies de l''information 13,73 % Services de communication 11,27 % Finance 10,61 % Santé 9,30 % Consommation discrétionnaire 7,86 % Industrie 4,04 % Biens de consommation de base 2,46 % Services aux collectivités 1,71 % Matériaux 0,95 % Énergie'),
  (16, '240', 'Diversifié sécurité (iA)', 'Fonds diversifiés', 'Revenu fixe canadien équilibré', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à combiner la croissance du capital au revenu courant tout en minimisant les risques grâce à la diversification entre les classes d''actif et à la combinaison de différents gestionnaires ayant des styles de gestion variés. —Solution gérée canadienne reconnue pour sa simplicité et son efficacité. —Expertise d’une équipe de gestionnaires chevronnés qui se penchent quotidiennement sur les décisions de placement.', '—Approche de gestion active basée sur les décisions de l''équipe responsable de la répartition d''actif, compte tenu des prévisions économiques et du marché. —Grande latitude quant aux limites de placements (± 20 % par rapport à la répartition cible).', 'Couverture active', '542,9 million', 'décembre 1998', '{"DDA": 2.11, "3mois": 1.07, "6mois": 2.11, "1an": 8.08, "3ans": 5.64, "5ans": 2.0, "10ans": 1.88, "depuis_lancement": 2.72}'::jsonb, '{"2024": 8.7, "2023": 5.01, "2022": -10.96, "2021": 2.06, "2020": 5.07, "2019": 7.84, "2018": -3.82, "2017": 2.64, "2016": 1.54, "2015": 3.54}'::jsonb, '66,45 % Canada 12,50 % États-Unis 10,82 % Mondial 5,18 % Court terme et autres 4,27 % International 0,78 % Asie et Pacifique'),
  (17, '250', 'Diversifié opportunité (iA)', 'Fonds diversifiés', 'Actions canadiennes équilibrées', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à combiner la croissance du capital au revenu courant tout en minimisant les risques grâce à la diversification entre les classes d''actif et à la combinaison de différents gestionnaires ayant des styles de gestion variés. —Solution gérée canadienne reconnue pour sa simplicité et son efficacité. —Expertise d’une équipe de gestionnaires chevronnés qui se penchent quotidiennement sur les décisions de placement.', '—Approche de gestion active basée sur les décisions de l''équipe responsable de la répartition d''actif, compte tenu des prévisions économiques et du marché. —Grande latitude quant aux limites de placements (± 20 % par rapport à la répartition cible).', 'Couverture active', '874,8 million', 'décembre 1998', '{"DDA": 4.65, "3mois": 3.68, "6mois": 4.65, "1an": 14.01, "3ans": 9.9, "5ans": 8.02, "10ans": 4.73, "depuis_lancement": 5.07}'::jsonb, '{"2024": 15.35, "2023": 7.11, "2022": -9.35, "2021": 12.91, "2020": 6.93, "2019": 14.19, "2018": -8.11, "2017": 5.21, "2016": 4.67, "2015": 1.92}'::jsonb, '64,24 % Canada 14,27 % Mondial 11,58 % États-Unis 4,98 % International 4,15 % Court terme et autres 0,78 % Asie et Pacifique'),
  (18, '270', 'Frontière Nord MD Fidelity', 'Fonds d''actions canadiennes', 'Actions canadiennes', 'Fidelity Investments', '—Fonds d''actions canadiennes de base qui vise à offrir un potentiel de croissance supérieur à long terme grâce aux occasions offertes par l''ensemble du marché boursier canadien. —Fonds investi principalement dans des actions canadiennes et le gestionnaire peut investir jusqu''à 30 % des actifs du Fonds dans des titres étrangers.', '—Vise à investir dans des sociétés appelées à croître à long terme et dont les titres se négocient à des prix raisonnables. —L''analyse fondamentale ascendante (« bottom-up ») des sociétés est le principal moteur de construction du portefeuille.', 'Sans couverture', '492,5 million', 'janvier 1999', '{"DDA": 9.12, "3mois": 8.21, "6mois": 9.12, "1an": 19.18, "3ans": 13.17, "5ans": 12.3, "10ans": 7.69, "depuis_lancement": 7.51}'::jsonb, '{"2024": 15.49, "2023": 9.38, "2022": -5.95, "2021": 22.35, "2020": 9.53, "2019": 16.53, "2018": -5.59, "2017": 4.27, "2016": 9.39, "2015": -2.4}'::jsonb, '27,31 % Finance 15,52 % Industrie 11,97 % Énergie 10,38 % Matériaux 10,26 % Technologies de l''information 9,19 % Biens de consommation de base 4,06 % Services aux collectivités 3,14 % Consommation discrétionnaire 2,86 % Services de communication 1,49 % Santé 0,64 % Multisectoriel 0,28 % Immobilier'),
  (19, '280', 'Potentiel Canada Fidelity', 'Fonds d''actions canadiennes', 'Actions canadiennes', 'Fidelity Investments', '—Fonds investi principalement dans des actions canadiennes et vise à offrir un rendement à long terme supérieur en ciblant le potentiel de croissance des sociétés à petite et moyenne capitalisation. —Le gestionnaire peut investir jusqu''à 30 % des actifs du Fonds dans des titres étrangers et jusqu''à 10 % dans des titres de sociétés privées.', '—Le gestionnaire utilise une approche à contre-courant (ou "contrarienne") qui vise à repérer la valeur parmi les actions délaissées.', 'Sans couverture', '1 930,1 million', 'janvier 1999', '{"DDA": 3.14, "3mois": 7.38, "6mois": 3.14, "1an": 9.2, "3ans": 14.14, "5ans": 13.74, "10ans": 10.08, "depuis_lancement": 8.49}'::jsonb, '{"2024": 9.94, "2023": 17.49, "2022": -2.85, "2021": 18.72, "2020": 27.01, "2019": 21.09, "2018": -1.49, "2017": 2.32, "2016": 24.05, "2015": -9.35}'::jsonb, '22,02 % Industrie 18,49 % Finance 18,21 % Matériaux 15,26 % Énergie 8,41 % Biens de consommation de base 7,67 % Technologies de l''information 5,64 % Consommation discrétionnaire 2,05 % Immobilier 1,92 % Services aux collectivités'),
  (20, '290', 'Actions Europe Fidelity', 'Fonds d''actions américaines et internationales', 'Actions européennes', 'Fidelity Investments', '—Le Fonds vise à offrir un potentiel de croissance supérieur en investissant sur le marché européen. —Tire parti de l''équipe de placement spécialisée « sur le terrain » et des ressources mondiales de Fidelity. —Portefeuille à forte conviction et géré activement.', '—Style : Qualité à un prix raisonnable (QUARP) —Fonds investi principalement dans des titres de sociétés du Royaume-Uni et du continent européen. —Vise à investir dans des sociétés ayant une franchise de haute qualité et une valorisation attrayante.', 'Sans couverture', '102,0 million', 'janvier 1999', '{"DDA": 11.85, "3mois": 2.76, "6mois": 11.85, "1an": 14.57, "3ans": 14.45, "5ans": 7.57, "10ans": 3.59, "depuis_lancement": 5.29}'::jsonb, '{"2024": 9.98, "2023": 13.46, "2022": -13.52, "2021": 9.38, "2020": -3.01, "2019": 14.42, "2018": -9.2, "2017": 15.51, "2016": -11.42, "2015": 18.47}'::jsonb, NULL),
  (21, '300', 'Indiciel international (BlackRock)', 'Fonds d''actions américaines et internationales', 'Actions internationales', 'BlackRock', '—Le Fonds vise à reproduire le rendement de l''indice MSCI EAEO. —Offre une exposition passive au marché boursier international.', '—BlackRock utilise une approche indicielle pour gérer le Fonds. —Fonds investi directement dans des actions émises en Europe, en Australasie et en Extrême-Orient.', 'Sans couverture', '420,8 million', 'septembre 1999', '{"DDA": 12.29, "3mois": 5.41, "6mois": 12.29, "1an": 14.35, "3ans": 15.16, "5ans": 8.39, "10ans": 4.78, "depuis_lancement": 5.75}'::jsonb, '{"2024": 9.92, "2023": 12.22, "2022": -10.46, "2021": 7.5, "2020": 3.21, "2019": 13.1, "2018": -8.35, "2017": 13.87, "2016": -4.91, "2015": 16.04}'::jsonb, NULL),
  (22, '310', 'Indiciel américain DAQ (iA)', 'Fonds spécialisés', 'Actions américaines', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à reproduire le rendement de l''indice Nasdaq 100, qui comprend 100 des plus grandes sociétés non financières cotées sur le marché boursier du Nasdaq en fonction de leur capitalisation boursière.', '—Fonds géré selon une approche indicielle. —Le rendement du Fonds est assujetti aux fluctuations de la devise canadienne.', 'Sans couverture', '2 729,6 million', 'septembre 1999', '{"DDA": 1.22, "3mois": 10.83, "6mois": 1.22, "1an": 12.27, "3ans": 24.87, "5ans": 14.77, "10ans": 16.39, "depuis_lancement": 17.31}'::jsonb, '{"2024": 33.06, "2023": 46.19, "2022": -29.47, "2021": 22.47, "2020": 41.51, "2019": 28.17, "2018": 5.86, "2017": 20.31, "2016": 1.09, "2015": 26.75}'::jsonb, '50,06 % Technologies de l''information 14,61 % Services de communication 12,66 % Consommation discrétionnaire 4,91 % Biens de consommation de base 4,56 % Santé 4,25 % Industrie 1,33 % Services aux collectivités 1,22 % Matériaux 0,43 % Énergie 0,40 % Finance 0,19 % Immobilier'),
  (23, '358', 'Actions mondiales de valeur opportuniste (Wellington)', 'Fonds d''actions américaines et internationales', 'Actions mondiales', 'Wellington Management', '—Cherche à surperformer l’indice MSCI Monde tous pays en investissant dans des sociétés décotées qui sont évitées ou négligées en raison de l’incertitude ou de la complaisance. —La stratégie est de rechercher des moteurs d’investissement non corrélés et une flexibilité du bilan qui ont le potentiel de diversification et de durabilité au long du cycle économique.', '—Approche d’investissement appuyée sur une recherche fondamentale intensive axée sur les sociétés disposant d’actifs uniques et dont les occasions d’amélioration de rendements sont mal comprises par le marché. —Le portefeuille est opportuniste dans sa sélection d’actions, il se concentre sur les sociétés défavorisées dont le changement de sentiment à leur égard a le potentiel d''être positif.', 'Défensive', '222,4 million', 'juillet 2021', '{"DDA": 2.2, "3mois": 1.07, "6mois": 2.2, "1an": 11.28, "3ans": 12.25}'::jsonb, '{"2024": 15.53, "2023": 8.09, "2022": -2.07}'::jsonb, '19,63 % Finance 13,39 % Technologies de l''information 11,55 % Consommation discrétionnaire 10,99 % Industrie 10,55 % Santé 7,57 % Services de communication 5,90 % Matériaux 5,71 % Biens de consommation de base 4,83 % Immobilier 4,41 % Énergie 3,90 % Services aux collectivités'),
  (24, '361', 'Croissance et revenu mondiaux (iA)', 'Fonds diversifiés', 'Équilibrés mondiaux neutres', 'iA Gestion mondiale d''actifs', '—Fonds équilibré flexible investissant principalement dans des actions mondiales et des titres à revenu fixe. —Exposition mondiale pouvant élargir l''univers d''investissement afin d''augmenter le potentiel de croissance.', '—Approche basée sur une gestion tactique de la répartition de l''actif, compte tenu des prévisions économiques et du marché en s''appuyant sur l''expertise de l''équipe dédiée d''experts en répartition d''actifs chez IAGAM. —Volet actions : sociétés mondiales de qualité élevée versant des dividendes et ayant la capacité de les augmenter au fil du temps pour créer un effet composé. —Volet revenu fixe : Portefeuille de première qualité complété d’une exposition diversifiée aux titres à revenu fixe non traditionnels, pour un potentiel de rendement supérieur.', 'Variable', '16,0 million', 'octobre 2024', '{"DDA": 0.87, "3mois": 0.31, "6mois": 0.87, "1an": 8.05}'::jsonb, '{"2024": 13.13}'::jsonb, NULL),
  (25, '362', 'Indexia obligations (iA)', 'Fonds Indexia', 'Revenu fixe canadien', 'BlackRock', '—Le Fonds vise à reproduire, dans la mesure du possible, le rendement de l''indice obligataire universel FTSE Canada. —Offre une exposition passive au marché obligataire canadien.', '—BlackRock utilise une approche indicielle pour gérer le Fonds. —Fonds investi dans un portefeuille largement diversifié de titres obligataires gouvernementaux et corporatifs situés au Canada.', 's.o.', '17,7 million', 'octobre 2024', '{"DDA": 0.46, "3mois": -1.01, "6mois": 0.46, "1an": 4.89}'::jsonb, '{"2024": 3.16}'::jsonb, NULL),
  (26, '363', 'Indexia actions canadiennes (iA)', 'Fonds Indexia', 'Actions canadiennes', 'BlackRock', '—Le Fonds vise à reproduire, dans la mesure du possible, le rendement de l''indice composé plafonné S&P/TSX. —Offre une exposition passive au marché boursier canadien.', '—BlackRock utilise une approche indicielle pour gérer le Fonds. —Fonds investi dans un portefeuille largement diversifié de titres de compagnies situées au Canada.', 's.o.', '4,4 million', 'octobre 2024', '{"DDA": 8.97, "3mois": 8.05, "6mois": 8.97, "1an": 24.92}'::jsonb, '{"2024": 20.39}'::jsonb, '32,65 % Finance 15,76 % Énergie 13,43 % Matériaux 12,76 % Industrie 9,77 % Technologies de l''information 3,78 % Services aux collectivités 3,71 % Biens de consommation de base 3,33 % Consommation discrétionnaire 2,21 % Services de communication 1,77 % Immobilier 0,25 % Santé'),
  (27, '364', 'Indexia actions américaines (iA)', 'Fonds Indexia', 'Actions américaines', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à reproduire, dans la mesure du possible, le rendement de l''indice CRSP US Total Market. —Offre une exposition passive aux actions américaines.', '—iAGMA utilise une approche indicielle pour gérer le Fonds. —Fonds investi dans un portefeuille largement diversifié de titres de compagnies américaines.', 'Sans couverture', '7,0 million', 'octobre 2024', '{"DDA": -1.36, "3mois": 4.36, "6mois": -1.36, "1an": 10.78}'::jsonb, '{"2024": 26.35}'::jsonb, '31,05 % Technologies de l''information 14,49 % Finance 10,44 % Consommation discrétionnaire 9,93 % Industrie 9,69 % Santé 9,14 % Services de communication 5,19 % Biens de consommation de base 3,09 % Énergie 2,48 % Immobilier 2,34 % Services aux collectivités 2,15 % Matériaux'),
  (28, '365', 'Indexia actions mondiales (iA)', 'Fonds Indexia', 'Actions mondiales', 'TD', '—Le Fonds vise à reproduire, dans la mesure du possible, le rendement de l''indice de rendement total MSCI Monde Ex-Canada. —Offre une exposition passive aux actions mondiales.', '—Gestion de Placements TD utilise une approche indicielle pour gérer le Fonds. —Fonds investi dans un portefeuille largement diversifié de titres de compagnies situées dans les pays développés à travers le monde.', 'Sans couverture', '5,4 million', 'octobre 2024', '{"DDA": 2.25, "3mois": 4.9, "6mois": 2.25, "1an": 13.35}'::jsonb, '{"2024": 27.75}'::jsonb, '24,34 % Technologies de l''information 10,20 % Finance 7,78 % Consommation discrétionnaire 6,91 % Santé 6,52 % Services de communication 6,48 % Industrie 3,96 % Biens de consommation de base 2,21 % Énergie 1,70 % Services aux collectivités 1,56 % Immobilier 1,46 % Matériaux 0,75 % Télécommunications'),
  (29, '401', 'Allocation d''actifs mondiaux sécurité (iA)', 'Fonds diversifiés', 'Équilibré mondial à revenu fixe', 'iA Gestion mondiale d''actifs', '—Portefeuille clé en main offrant une diversification accrue au sein de différentes classes d’actifs et de multiples régions à travers le monde. —Expertise d''une équipe de gestionnaires qui se penchent quotidiennement sur les décisions de placement.', '—Style : Gestion active —Grande latitude accordée au gestionnaire quant aux limites de placements, avec possibilité d''investir dans des placements alternatifs faiblement corrélés aux marchés traditionnels.', 'Couverture active', '78,5 million', 'octobre 2018', '{"DDA": 2.13, "3mois": 0.85, "6mois": 2.13, "1an": 7.85, "3ans": 5.5, "5ans": 2.29, "10ans": null, "depuis_lancement": 2.67}'::jsonb, '{"2024": 8.2, "2023": 5.57, "2022": -11.92, "2021": 2.35, "2020": 5.86, "2019": 7.07, "2018": null, "2017": null, "2016": null, "2015": null}'::jsonb, 'cibleFonds de revenu fixe 66,50 % Fonds d''actions étrangères 25,50 % Fonds spécialisés - alternatifs 8,00 %'),
  (30, '402', 'Allocation d''actifs mondiaux (iA)', 'Fonds diversifiés', 'Équilibrés mondiaux neutres', 'iA Gestion mondiale d''actifs', '—Portefeuille clé en main offrant une diversification accrue au sein de différentes classes d’actifs et de multiples régions à travers le monde. —Expertise d''une équipe de gestionnaires qui se penchent quotidiennement sur les décisions de placement.', '—Style : Gestion active —Grande latitude accordée au gestionnaire quant aux limites de placements, avec possibilité d''investir dans des placements alternatifs faiblement corrélés aux marchés traditionnels.', 'Couverture active', '171,7 million', 'octobre 2018', '{"DDA": 3.31, "3mois": 2.22, "6mois": 3.31, "1an": 10.3, "3ans": 8.64, "5ans": 5.21, "10ans": null, "depuis_lancement": 5.01}'::jsonb, '{"2024": 12.44, "2023": 7.56, "2022": -11.07, "2021": 6.38, "2020": 7.16, "2019": 10.41, "2018": null, "2017": null, "2016": null, "2015": null}'::jsonb, 'cibleFonds de revenu fixe 46,50 % Fonds d''actions étrangères 44,50 % Fonds spécialisés - alternatifs 9,00 %'),
  (31, '403', 'Allocation d''actifs mondiaux opportunité (iA)', 'Fonds diversifiés', 'Équilibrés mondiaux d''actions', 'iA Gestion mondiale d''actifs', '—Portefeuille clé en main offrant une diversification accrue au sein de différentes classes d’actifs et de multiples régions à travers le monde. —Expertise d''une équipe de gestionnaires qui se penchent quotidiennement sur les décisions de placement.', '—Style : Gestion active —Grande latitude accordée au gestionnaire quant aux limites de placements, avec possibilité d''investir dans des placements alternatifs faiblement corrélés aux marchés traditionnels.', 'Couverture active', '67,9 million', 'octobre 2018', '{"DDA": 4.6, "3mois": 3.3, "6mois": 4.6, "1an": 12.33, "3ans": 10.74, "5ans": 7.46, "10ans": null, "depuis_lancement": 6.76}'::jsonb, '{"2024": 14.94, "2023": 8.69, "2022": -10.24, "2021": 9.58, "2020": 8.15, "2019": 12.5, "2018": null, "2017": null, "2016": null, "2015": null}'::jsonb, 'cibleFonds de revenu fixe 23,00 % Fonds d''actions étrangères 67,00 % Fonds spécialisés - alternatifs 10,00 %'),
  (32, '464', 'Actions canadiennes - croissance (iA)', 'Fonds d''actions canadiennes', 'Actions canadiennes', 'iA Gestion mondiale d''actifs', '—Une stratégie canadienne de base investie principalement dans des sociétés à grande capitalisation. —Le Fonds vise à dépasser l’indice de référence tout en affichant une volatilité moindre (risque plus faible).', '—Style : Biais de croissance avec une attention au prix —Composé généralement de 5 % à 15 % de titres de sociétés à petite et à moyenne capitalisation. —Peut investir jusqu’à 30 % en titres américains, généralement dans les secteurs de la santé et des technologies de l’information. —Le gestionnaire porte une attention particulière à la gestion des risques sur le plan des secteurs, des capitalisations et des principales positions dans l''indice de référence.', 'Couverture active', '1 354,6 million', 'octobre 2001', '{"DDA": 8.55, "3mois": 8.28, "6mois": 8.55, "1an": 21.31, "3ans": 13.69, "5ans": 13.81, "10ans": 7.84, "depuis_lancement": 6.63}'::jsonb, '{"2024": 18.1, "2023": 10.7, "2022": -6.07, "2021": 23.75, "2020": 5.77, "2019": 19.33, "2018": -10.82, "2017": 8.22, "2016": 14.96, "2015": -5.46}'::jsonb, '29,34 % Finance 13,75 % Industrie 12,93 % Énergie 11,05 % Matériaux 10,46 % Technologies de l''information 6,16 % Biens de consommation de base 4,89 % Consommation discrétionnaire 4,04 % Services aux collectivités 3,22 % Services de communication 1,84 % Immobilier 0,42 % Santé'),
  (33, '470', 'Soins de santé mondiaux (Renaissance)', 'Fonds spécialisés', 'Actions sectorielles', 'Gestion d’actifs CIBC', '—Fonds investi principalement dans des sociétés américaines qui sont engagées dans la conception, le développement, la fabrication et la distribution de produits ou de services dans les secteurs des soins de santé. —Vise à surperformer de manière significative à long terme en capitalisant sur la croissance des dépenses mondiales en matière de soins de santé et d’innovation.', '—Le Fonds utilise une approche fondamentale ascendante, combinée à une compréhension des principales tendances scientifiques, médicales, réglementaires et économiques affectant le secteur mondial de la santé, afin d''investir dans des sociétés innovantes de haute qualité. —Fonds investi dans un portefeuille diversifié de titres dans les secteurs de la technologie médicale, de la biotechnologie, des soins de santé et de la pharmacie.', 'Sans couverture', '275,4 million', 'septembre 2001', '{"DDA": -7.98, "3mois": -10.94, "6mois": -7.98, "1an": -3.22, "3ans": 1.64, "5ans": 0.3, "10ans": 2.58, "depuis_lancement": 9.46}'::jsonb, '{"2024": 10.18, "2023": -3.3, "2022": -7.31, "2021": 7.77, "2020": 8.66, "2019": 16.37, "2018": 5.87, "2017": 4.92, "2016": -13.74, "2015": 30.64}'::jsonb, NULL),
  (34, '474', 'Indiciel canadien (iA)', 'Fonds d''actions canadiennes', 'Actions canadiennes', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à reproduire le rendement de l''indice S&P/TSX 60. —Offre une exposition passive au marché boursier canadien.', '—Fonds géré selon un style de gestion indicielle en investissant directement dans des actions émises au Canada.', 's.o.', '1 091,7 million', 'septembre 2001', '{"DDA": 7.96, "3mois": 6.8, "6mois": 7.96, "1an": 22.77, "3ans": 12.29, "5ans": 11.81, "10ans": 7.05, "depuis_lancement": 5.6}'::jsonb, '{"2024": 17.65, "2023": 8.91, "2022": -8.64, "2021": 24.56, "2020": 3.07, "2019": 18.15, "2018": -9.69, "2017": 7.01, "2016": 17.9, "2015": -10.01}'::jsonb, '34,83 % Finance 15,13 % Énergie 10,62 % Matériaux 10,15 % Industrie 10,09 % Technologies de l''information 3,88 % Biens de consommation de base 3,55 % Consommation discrétionnaire 2,88 % Services aux collectivités 2,36 % Services de communication 0,52 % Immobilier'),
  (35, '502', 'Revenu immobilier (iA)', 'Fonds spécialisés', 'Actions de l’immobilier', 'iA Gestion mondiale d''actifs', '—Fonds investi principalement dans un portefeuille diversifié de fiducies de placement immobilier (FPI) canadiennes, et veille à l''équilibre et à la diversification en investissant généralement entre 15 % et 25 % dans des actions canadiennes qui versent des dividendes. —Les FPI ont tendance à avoir un taux de distribution supérieur à celui des sociétés, et illustrent une faible corrélation avec les classes d''actifs traditionnelles.', '—Approche de placement ascendante tout en assurant une saine diversification entre les différents sous-secteurs de l’immobilier canadien, selon une analyse macroéconomique ou une thématique spécifique. —Bon équilibre entre les FPI canadiennes (65 à 75 %) et les actions à dividendes canadiennes (15 à 25 %). —Portefeuille à forte conviction composée de 30 à 60 titres.', 's.o.', '137,2 million', 'octobre 2003', '{"DDA": 6.65, "3mois": 5.9, "6mois": 6.65, "1an": 11.39, "3ans": 2.07, "5ans": 4.81, "10ans": 3.4, "depuis_lancement": 4.76}'::jsonb, '{"2024": -3.43, "2023": 2.24, "2022": -16.87, "2021": 29.75, "2020": -10.11, "2019": 16.67, "2018": 1.0, "2017": 6.45, "2016": 12.33, "2015": -1.62}'::jsonb, '88,61 % Immobilier 2,92 % Services aux collectivités 1,85 % Énergie 0,96 % Industrie 0,75 % Santé'),
  (36, '505', 'Asie pacifique (iA)', 'Fonds spécialisés', 'Actions de l’Asie-Pacifique', 'iA Gestion mondiale d''actifs', '—Le Fonds offre une exposition aux occasions d''investissement en Extrême-Orient par le biais d''une approche quantitative multifactorielle.', '—L''approche de placement vise à identifier et à investir dans des titres offrant une exposition à de multiples sources de rendement (facteurs) pour un potentiel amélioré de performance et de diversification. —Le Fonds vise à maintenir une diversification géographique similaire à celle de l''indice.', 'Sans couverture', '206,3 million', 'décembre 1999', '{"DDA": 6.57, "3mois": 5.03, "6mois": 6.57, "1an": 13.6, "3ans": 10.73, "5ans": 4.27, "10ans": 5.71, "depuis_lancement": 5.17}'::jsonb, '{"2024": 20.81, "2023": 11.87, "2022": -25.12, "2021": -11.64, "2020": 44.42, "2019": 26.12, "2018": -11.83, "2017": 26.45, "2016": -6.18, "2015": 7.5}'::jsonb, '20,63 % Finance 18,55 % Technologies de l''information 14,12 % Consommation discrétionnaire 12,29 % Industrie 9,15 % Services de communication 5,57 % Matériaux 4,70 % Santé 3,94 % Biens de consommation de base 2,58 % Immobilier 2,35 % Énergie 1,84 % Services aux collectivités'),
  (37, '515', 'Dividendes croissance (iA)', 'Fonds d''actions canadiennes', 'Actions canadiennes de dividendes et de revenu', 'iA Gestion mondiale d''actifs', '—Un portefeuille de base axé sur les dividendes, composé principalement d’actions de grandes sociétés canadiennes qui s’efforcent de verser des dividendes réguliers et croissants. —Le Fonds peut investir jusqu''à 30 % de ses actifs dans des titres étrangers.', '—Le gestionnaire utilise une approche ascendante, à forte conviction, pour sélectionner des titres de sociétés offrant des valorisations attrayantes, des bilans solides et d''excellentes équipes de gestion. —Le Fonds est généralement positionné de manière légèrement défensive et conservatrice.', 'Couverture active', '1 857,2 million', 'novembre 2005', '{"DDA": 5.67, "3mois": 2.76, "6mois": 5.67, "1an": 18.31, "3ans": 10.21, "5ans": 12.1, "10ans": 7.34, "depuis_lancement": 6.7}'::jsonb, '{"2024": 19.99, "2023": 5.77, "2022": -5.27, "2021": 22.79, "2020": -2.04, "2019": 18.08, "2018": -7.92, "2017": 6.69, "2016": 17.72, "2015": -4.65}'::jsonb, '32,30 % Finance 20,12 % Énergie 11,29 % Industrie 7,97 % Matériaux 7,71 % Technologies de l''information 5,42 % Services de communication 4,42 % Biens de consommation de base 4,18 % Services aux collectivités 2,98 % Santé 2,60 % Consommation discrétionnaire'),
  (38, '516', 'Actions revenu stratégique (iA)', 'Fonds d''actions canadiennes', 'Actions canadiennes de dividendes et de revenu', 'iA Gestion mondiale d''actifs', '—Fonds investi principalement dans les actions de sociétés de grande qualité considérées être sous-évaluées par le gestionnaire, qui versent des dividendes et qui présentent un potentiel de croissance. —Le gestionnaire peut investir jusqu''à 49 % des actifs du Fonds dans des titres étrangers.', '—Processus d''investissement actif et rigoureux axé sur la sécurité des revenus et aligné avec les perspectives macroéconomiques du gestionnaire. —Le gestionnaire vise à positionner stratégiquement le Fonds, peu importe les conditions économiques.', 'Couverture active', '265,8 million', 'novembre 2005', '{"DDA": 7.14, "3mois": 7.39, "6mois": 7.14, "1an": 16.99, "3ans": 9.39, "5ans": 11.17, "10ans": 6.21, "depuis_lancement": 6.33}'::jsonb, '{"2024": 13.38, "2023": 7.62, "2022": -8.81, "2021": 26.32, "2020": -2.36, "2019": 14.95, "2018": -5.18, "2017": 6.33, "2016": 10.02, "2015": -3.28}'::jsonb, '29,41 % Finance 20,83 % Industrie 8,44 % Énergie 7,90 % Services aux collectivités 6,35 % Immobilier 5,66 % Biens de consommation de base 5,08 % Services de communication 3,12 % Santé 2,97 % Consommation discrétionnaire 2,39 % Technologies de l''information 1,36 % Matériaux'),
  (39, '517', 'Fidelity Étoile du Nord MD', 'Fonds d''actions américaines et internationales', 'Actions mondiales à petite et moyenne capitalisation', 'Fidelity Investments', '—Fonds investi principalement dans des titres de capitaux propres mondiaux. —Propose une stratégie sans contraintes qui vise à investir dans les meilleures sociétés situées n''importe où dans le monde. —Gestion assurée par deux gestionnaires de portefeuilles chevronnés qui bénéficient du soutien des ressources mondiales de Fidelity.', '—Le Fonds peut parfois concentrer ses avoirs dans un nombre relativement restreint de sociétés, de secteurs, de pays ou de sociétés de même taille, selon les convictions de ses gestionnaires. —L’approche de cogestion unique vise à atténuer les risques de pertes durant les périodes de volatilité des marchés.', 'Sans couverture', '210,6 million', 'novembre 2005', '{"DDA": 4.34, "3mois": 5.66, "6mois": 4.34, "1an": 12.78, "3ans": 15.75, "5ans": 10.71, "10ans": 6.04, "depuis_lancement": 8.47}'::jsonb, '{"2024": 20.06, "2023": 13.62, "2022": -7.16, "2021": 6.93, "2020": 19.28, "2019": 4.16, "2018": -5.79, "2017": 3.44, "2016": -2.63, "2015": 24.05}'::jsonb, NULL),
  (40, '518', 'Dividendes croissance américains (iA)', 'Fonds d''actions américaines et internationales', 'Actions américaines', 'iA Gestion mondiale d''actifs', '—Fonds investi principalement dans des actions de sociétés américaines à grande capitalisation versant des dividendes qui, selon l''avis du gestionnaire, représentent des évaluations intéressantes, des bilans vigoureux et d’excellentes équipes de gestion.', '—Un procédé de placement discipliné qui combine l’analyse macroéconomique descendante et l’analyse fondamentale ascendante mettant l’accent sur la gestion des risques. —Portefeuille à forte conviction de 55 à 75 actions de croissance des dividendes.', 'Couverture active', '611,5 million', 'octobre 2005', '{"DDA": -1.2, "3mois": -0.15, "6mois": -1.2, "1an": 11.21, "3ans": 15.23, "5ans": 12.83, "10ans": 8.66, "depuis_lancement": 10.09}'::jsonb, '{"2024": 30.6, "2023": 8.52, "2022": -3.58, "2021": 22.24, "2020": 6.16, "2019": 19.31, "2018": -7.61, "2017": 8.72, "2016": 0.19, "2015": 19.38}'::jsonb, '17,45 % Finance 16,71 % Technologies de l''information 13,76 % Industrie 9,65 % Matériaux 9,39 % Santé 8,78 % Biens de consommation de base 7,14 % Consommation discrétionnaire 7,07 % Services de communication 4,91 % Services aux collectivités 2,34 % Immobilier 2,26 % Énergie'),
  (41, '530', 'Diversifié mondial (Loomis Sayles)', 'Fonds diversifiés', 'Équilibrés mondiaux d''actions', 'Loomis, Sayles & Company', '—Une stratégie de répartition d’actif sans contraintes ni restrictions, qui vise à investir dans de multiples classes d’actifs, de secteurs, de pays et de devises. —Un portefeuille à la fois concentré et bien diversifié basé sur les idées à plus forte conviction. —Une collaboration continue entre les équipes, appuyée par la plate-forme avancée de recherche mondiale de Loomis Sayles.', '—Équilibre entre actions mondiales (50 à 70 %) et titres à revenu fixe américains et mondiaux (30 à 50 %) —Volet d''actions mondiales à forte conviction : sélection de titres ascendante et flexibilité par rapport à la matrice de style. —Approche opportuniste de la gestion des titres à revenu fixe, axée sur le risque propre à chaque titre.', 'Revenu fixe (couverture active) / Actions (sans couverture)', '1 901,3 million', 'novembre 2006', '{"DDA": -0.34, "3mois": 2.44, "6mois": -0.34, "1an": 6.43, "3ans": 13.19, "5ans": 6.24, "10ans": 6.81, "depuis_lancement": 5.98}'::jsonb, '{"2024": 18.17, "2023": 17.68, "2022": -19.8, "2021": 11.99, "2020": 11.13, "2019": 19.79, "2018": -1.06, "2017": 13.49, "2016": 1.86, "2015": 3.04}'::jsonb, '19,98 % Technologies de l''information 13,67 % Finance 11,35 % Consommation discrétionnaire 10,94 % Industrie 4,79 % Santé 2,07 % Matériaux 1,95 % Services de communication 1,93 % Biens de consommation de base 0,41 % Énergie'),
  (42, '532', 'Dividende mondial (Dynamique)', 'Fonds d''actions américaines et internationales', 'Actions mondiales', 'Fonds Dynamique', '—Fonds d''actions mondial qui privilégie les titres de sociétés à grande capitalisation et les États Unis dans le but de réduire la volatilité. —Le gestionnaire recherche des sociétés sous-évaluées qui offrent la capacité de verser des dividendes ou de les accroître.', '—Style : Qualité et croissance des dividendes —Emphase mise sur les sociétés ayant une bonne équipe de direction, qui dominent leur industrie et qui possèdent un avantage concurrentiel durable. —Le processus d''investissement ascendant résulte en un portefeuille à forte conviction (position active élevée).', 'Sans couverture, mais peut couvrir de façon opportuniste', '1 444,0 million', 'novembre 2006', '{"DDA": 1.02, "3mois": 6.37, "6mois": 1.02, "1an": 6.98, "3ans": 9.29, "5ans": 5.41, "10ans": 8.46, "depuis_lancement": 8.84}'::jsonb, '{"2024": 23.55, "2023": 2.84, "2022": -18.77, "2021": 13.18, "2020": 11.15, "2019": 22.85, "2018": 4.19, "2017": 21.12, "2016": -0.64, "2015": 21.61}'::jsonb, '32,20 % Technologies de l''information 20,30 % Finance 20,30 % Industrie 10,80 % Services de communication 6,50 % Consommation discrétionnaire 3,50 % Services aux collectivités 1,90 % Biens de consommation de base'),
  (43, '541', 'Actions canadiennes à petite capitalisation (QV)', 'Fonds d''actions canadiennes', 'Actions canadiennes à petite et moyenne capitalisation', 'QV Investors Inc.', '—Le Fonds vise à maximiser la croissance du capital à long terme en investissant principalement dans des titres de sociétés canadiennes à petite capitalisation. —Le gestionnaire peut investir jusqu''à 30 % des actifs du Fonds dans des titres étrangers. —Un portefeuille complémentaire cherchant à investir dans des sociétés qui, selon le gestionnaire, ont des avantages concurrentiels durables.', '—Fonds investi dans des sociétés de qualité ayant des évaluations inférieures mais croissant à des taux plus élevés que le marché, et qui versent généralement un dividende. —Portefeuille de 25 à 40 des meilleures idées du gestionnaire, qui offre des pondérations sectorielles individuelles généralement de moins de 25 % en vue d''assurer la diversification.', 'Sans couverture', '234,0 million', 'décembre 2006', '{"DDA": 9.1, "3mois": 12.87, "6mois": 9.1, "1an": 17.24, "3ans": 14.35, "5ans": 15.35, "10ans": 7.06, "depuis_lancement": 8.56}'::jsonb, '{"2024": 13.03, "2023": 9.95, "2022": 0.33, "2021": 24.13, "2020": 0.25, "2019": 15.07, "2018": -12.42, "2017": 1.8, "2016": 22.09, "2015": -7.04}'::jsonb, '19,77 % Industrie 15,12 % Finance 14,52 % Consommation discrétionnaire 13,05 % Énergie 12,78 % Matériaux 5,71 % Immobilier 4,29 % Santé 4,24 % Biens de consommation de base 4,13 % Services aux collectivités 2,72 % Technologies de l''information 1,97 % Services de communication'),
  (44, '579', 'Actions mondiales Conviction (iA)', 'Fonds d''actions américaines et internationales', 'Actions mondiales', 'iA Gestion mondiale d''actifs', '—Le Fonds offre une exposition mondiale par le biais d''un portefeuille d''actions à haute conviction, dont environ un tiers est situé au Canada et deux tiers à l''étranger. —Les deux gestionnaires de sous-portefeuilles cherchent à tirer parti de leurs meilleurs idées d''investissement dans chaque segment géographique.', '—Environ 70 titres sont répartis entre le Canada (max. 15) et les marchés mondiaux (max. 55). —Tout en donnant la priorité aux idées d’investissement à fort potentiel, les gestionnaires intègrent également des critères de gestion des risques afin d’assurer une saine diversification sectorielle.', 'Sans couverture', '208,6 million', 'janvier 2011', '{"DDA": 5.72, "3mois": 6.81, "6mois": 5.72, "1an": 15.07, "3ans": 17.31, "5ans": 11.36, "10ans": 7.56, "depuis_lancement": 8.32}'::jsonb, '{"2024": 23.55, "2023": 19.1, "2022": -15.73, "2021": 14.2, "2020": 14.29, "2019": 18.25, "2018": -7.9, "2017": 12.43, "2016": -1.73, "2015": 14.84}'::jsonb, '19,16 % Technologies de l''information 18,57 % Finance 13,45 % Industrie 12,19 % Matériaux 9,87 % Consommation discrétionnaire 5,20 % Énergie 4,74 % Services de communication 4,26 % Santé 3,41 % Services aux collectivités 1,72 % Biens de consommation de base'),
  (45, '604', 'Portefeuille géré de revenu fixe (iA)', 'Fonds de revenu', 'Revenu fixe mondial', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à fournir une exposition mondiale diversifiée aux titres à revenu fixe grâce à la gestion active de fonds à revenu fixe sous-jacents. —Balises d’investissement larges et flexibles visant à performer dans de nombreux types de cycles économiques et de conditions de marché.', '—Approche basée sur une gestion active de la répartition de l''actif, compte tenu des prévisions économiques et du marché. —Portefeuille de première qualité complété d’une exposition diversifiée aux titres à revenu fixe non traditionnels, pour un potentiel de rendement supérieur. —Utilisation opportuniste de fonds négociés en Bourse (FNB) pour permettre des répartitions tactiques.', 'Variable', '327,1 million', 'octobre 2021', '{"DDA": 1.98, "3mois": 0.26, "6mois": 1.98, "1an": 4.29, "3ans": 2.51, "5ans": -0.09}'::jsonb, '{"2024": 1.77, "2023": 3.96, "2022": -10.2, "2021": -1.4}'::jsonb, NULL),
  (46, '605', 'Obligations mondiales multisectorielles (Loomis Sayles)', 'Fonds de revenu', 'Revenu fixe multisectorielle', 'Loomis, Sayles & Company', '—Fonds investi principalement dans des obligations mondiales. —La structure flexible permet au gestionnaire d''exploiter au maximum les occasions de placement sous-évaluées dans de nombreux segments et parmi les différents rangs de capitaux.', '—Les gestionnaires du Fonds favorisent une approche de crédit guidée par les occasions et la valeur, centrée sur le risque propre à chaque titre. —Le procédé de placement discipliné et collaboratif, soutenu par la plateforme de recherche mondiale approfondie de Loomis Sayles, assure que seules leurs meilleures idées sont représentées dans le Fonds.', 'Couverture totale', '46,2 million', 'octobre 2021', '{"DDA": 2.72, "3mois": 1.25, "6mois": 2.72, "1an": 6.19, "3ans": 2.73, "5ans": -0.13}'::jsonb, '{"2024": 2.95, "2023": 4.38, "2022": -14.34, "2021": -1.45}'::jsonb, '62,44 % États-Unis 10,31 % Court terme et autres 9,63 % Amérique Latine 8,08 % Europe 6,13 % Asie et Pacifique 1,84 % Canada 1,57 % Moyen Orient et Afrique'),
  (47, '606', 'Fidelity Actions d''innovation et Obligations multisectorielles', 'Fonds diversifiés', 'Équilibrés mondiaux d''actions', 'Fidelity Investments', '—Fonds investi dans une combinaison de deux stratégies distinctes : le Fonds Fidelity Obligations multisectorielles - Devises neutres et le Fonds Fidelity Innovations mondiales MC . —Gestionnaires de portefeuille chevronnés ayant fait leurs preuves à long terme et soutenus par les compétences en recherche mondiales de Fidelity.', '—La répartition cible du Fonds correspond à 60 % en actions et 40 % en titres à revenu fixe, mais le Fonds peut s''en éloigner dans une proportion de ±20 %. —Stratégie d''actions flexible qui vise à tirer parti d''idées novatrices à l''échelle mondiale, combinée à une stratégie de titres à revenu fixe multi-sectorielle axée sur l''atténuation des risques.', 'Partiellement sans couverture', '221,1 million', 'octobre 2021', '{"DDA": 3.24, "3mois": 8.43, "6mois": 3.24, "1an": 11.7, "3ans": 18.48, "5ans": null, "10ans": null, "depuis_lancement": 6.89}'::jsonb, '{"2024": 31.79, "2023": 26.81, "2022": -23.9, "2021": -2.84}'::jsonb, NULL),
  (48, '607', 'Fidelity Innovations mondiales MC', 'Fonds spécialisés', 'Actions mondiales', 'Fidelity Investments', '—Mandat souple qui cible les sociétés novatrices et perturbatrices dans un monde en constante évolution. —Profite de la vaste plateforme de recherche mondiale de Fidelity en cherchant à saisir les occasions de placement prometteuses au sein des pays développés et émergents. —Gestionnaire de portefeuille d’expérience et de renom, ayant reçu de nombreuses distinctions.', '—Style : Thématique et croissance élevée —Fonds investi dans des titres de sociétés qui sont susceptibles de tirer parti de l''application de technologies novatrices et émergentes ou qui utilisent des modèles d''affaires novateurs. —Peut être investi dans les sociétés à petite, moyenne et grande capitalisation, y compris les sociétés privées.', 'Sans couverture', '971,2 million', 'octobre 2021', '{"DDA": 3.02, "3mois": 13.51, "6mois": 3.02, "1an": 16.59, "3ans": 29.9, "5ans": 18.13}'::jsonb, '{"2024": 57.03, "2023": 43.71, "2022": -31.23, "2021": 1.34}'::jsonb, NULL),
  (49, '705', 'Actions américaines (iA)', 'Fonds d''actions américaines et internationales', 'Actions américaines', 'iA Gestion mondiale d''actifs', '—Le Fonds offre une exposition à un portefeuille d''actions américaines de base par le biais d''une approche quantitative multifactorielle.', '—L''approche de placement vise à identifier et à investir dans des titres offrant une exposition à de multiples sources de rendement (facteurs) pour un potentiel amélioré de performance et de diversification. —Portefeuille bien diversifié (entre 150 et 300 titres).', 'Sans couverture', '186,4 million', 'septembre 2001', '{"DDA": -1.01, "3mois": 3.47, "6mois": -1.01, "1an": 12.56, "3ans": 16.35, "5ans": 12.36, "10ans": 8.7, "depuis_lancement": 10.72}'::jsonb, '{"2024": 31.78, "2023": 13.38, "2022": -12.74, "2021": 24.42, "2020": 14.07, "2019": 16.84, "2018": -8.23, "2017": 8.45, "2016": -1.5, "2015": 21.32}'::jsonb, '29,10 % Technologies de l''information 12,24 % Services de communication 11,25 % Consommation discrétionnaire 11,13 % Finance 8,19 % Industrie 8,11 % Santé 5,64 % Biens de consommation de base 3,58 % Services aux collectivités 3,06 % Énergie 2,62 % Matériaux 2,33 % Immobilier'),
  (50, '706', 'Actions internationales (iA)', 'Fonds d''actions américaines et internationales', 'Actions internationales', 'iA Gestion mondiale d''actifs', '—Le Fonds offre une exposition au potentiel du marché des actions internationales par le biais d''une approche quantitative multifactorielle.', '—L''approche de placement vise à identifier et à investir dans des titres offrant une exposition à de multiples sources de rendement (facteurs) pour un potentiel amélioré de performance et de diversification. —Portefeuille bien diversifié (500 titres et plus).', 'Sans couverture, mais peut couvrir de façon opportuniste', '571,0 million', 'novembre 2008', '{"DDA": 12.91, "3mois": 4.82, "6mois": 12.91, "1an": 17.07, "3ans": 17.18, "5ans": 8.16, "10ans": 5.25, "depuis_lancement": 6.0}'::jsonb, '{"2024": 12.86, "2023": 15.17, "2022": -10.8, "2021": 1.53, "2020": 6.96, "2019": 16.51, "2018": -12.1, "2017": 18.29, "2016": -8.22, "2015": 20.94}'::jsonb, '23,21 % Finance 16,77 % Industrie 10,59 % Santé 9,58 % Consommation discrétionnaire 8,25 % Services de communication 7,86 % Biens de consommation de base 6,11 % Technologies de l''information 5,34 % Matériaux 3,47 % Services aux collectivités 2,67 % Immobilier 2,02 % Énergie'),
  (51, '707', 'Actions mondiales (iA)', 'Fonds d''actions américaines et internationales', 'Actions mondiales', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à réaliser une appréciation du capital à long terme en investissant principalement dans un portefeuille diversifié de titres de capitaux propres de sociétés à grande capitalisation situées à travers le monde. —Peut servir à titre de portefeuille de base pour une diversification mondiale.', '—Approche de placement systématique et multifactorielle, fondée sur des recherches académiques approfondies, visant à identifier les actions qui présentent des caractéristiques favorables parmi plus de deux douzaines de facteurs liés au momentum, à la qualité et à la valeur.', 'Sans couverture, mais peut couvrir de façon opportuniste', '350,3 million', 'octobre 2005', '{"DDA": 1.97, "3mois": 3.69, "6mois": 1.97, "1an": 14.01, "3ans": 17.85, "5ans": 11.68, "10ans": 8.0, "depuis_lancement": 8.93}'::jsonb, '{"2024": 28.51, "2023": 16.4, "2022": -12.27, "2021": 16.52, "2020": 11.31, "2019": 17.44, "2018": -9.29, "2017": 14.01, "2016": -4.1, "2015": 19.96}'::jsonb, '20,43 % Technologies de l''information 15,57 % Finance 11,33 % Industrie 10,90 % Consommation discrétionnaire 10,39 % Services de communication 8,54 % Santé 5,07 % Biens de consommation de base 3,98 % Matériaux 3,65 % Énergie 2,91 % Services aux collectivités 1,67 % Immobilier'),
  (52, '761', 'Stratégie revenu (iA)', 'Fonds diversifiés', 'Équilibré canadien neutre', 'iA Gestion mondiale d''actifs', '—Fonds équilibré flexible et axé sur le revenu, principalement investi dans des actions et des titres à revenu fixe canadiens. —Le gestionnaire peut investir jusqu''à 49 % des actifs du Fonds dans des titres étrangers. —Le gestionnaire peut investir jusqu''à 70 % dans une catégorie d''actifs, ce qui permet au portefeuille de s''ajuster au marché.', '—Processus d''investissement actif et rigoureux axé sur la sécurité des revenus et incorporant les perspectives macroéconomiques du gestionnaire. —La composante de revenu fixe comprend des obligations de société à haut rendement, dont la sensibilité aux taux d''intérêt peut être inférieure à celle des obligations de première qualité.', 'Couverture active', '639,2 million', 'janvier 2012', '{"DDA": 5.22, "3mois": 4.62, "6mois": 5.22, "1an": 12.28, "3ans": 6.97, "5ans": 7.8, "10ans": 4.74, "depuis_lancement": 5.4}'::jsonb, '{"2024": 10.42, "2023": 5.36, "2022": -8.06, "2021": 16.27, "2020": -0.7, "2019": 12.88, "2018": -3.54, "2017": 5.22, "2016": 13.61, "2015": -6.16}'::jsonb, '62,99 % Canada 32,77 % États-Unis 4,24 % Court terme et autres'),
  (53, '762', 'Spécialisés Stratégie d''obligations de sociétés (iA)', 'Fonds de revenu', 'Revenu fixe à rendement élevé', 'iA Gestion mondiale d''actifs', '—Le Fonds vise à procurer un revenu et un potentiel de croissance du capital à long terme en investissant principalement dans des obligations de sociétés à rendement élevé. —Les titres de créance à rendement élevé peuvent avoir une moins grande sensibilité aux taux d’intérêt que les obligations de qualité supérieure.', '—Processus de placement rigoureux mettant l''accent sur la sécurité du revenu et incorporant les perspectives macroéconomiques du gestionnaire. —Le gestionnaire ajuste la qualité du crédit du portefeuille en fonction des conditions du marché.', 'Couverture active', '400,2 million', 'janvier 2012', '{"DDA": 1.73, "3mois": 1.11, "6mois": 1.73, "1an": 5.52, "3ans": 5.31, "5ans": 4.21, "10ans": 2.75, "depuis_lancement": 3.5}'::jsonb, '{"2024": 6.72, "2023": 6.18, "2022": -6.45, "2021": 4.92, "2020": 2.81, "2019": 4.94, "2018": -1.73, "2017": 2.56, "2016": 15.94, "2015": -4.92}'::jsonb, '68,74 % Canada 24,26 % États-Unis 4,46 % Court terme et autres 2,32 % Europe 0,22 % Moyen Orient et Afrique'),
  (54, '816', 'Focus prudent (iA)', 'Fonds Focus', 'Équilibrés mondiaux d''actions', 'iA Gestion mondiale d''actifs', '—Portefeuille clé en main pour les investisseurs qui souhaitent que leur tolérance au risque soit respectée en tout temps. —Pour l''expertise des gestionnaires de portefeuilles sous-jacents, sélectionnés par nos experts.', '—Style : Portefeuille à répartition de l''actif fixe, rééquilibré mensuellement. —Approche multigestion qui offre différents styles de gestion complémentaires. —Portefeuille bien diversifié par catégories d’actifs, régions géographiques et secteurs économiques.', 'Variable', '320,2 million', 'octobre 2002', '{"DDA": 2.0, "3mois": 0.89, "6mois": 2.0, "1an": 7.21, "3ans": 5.98, "5ans": 2.2, "10ans": 1.99, "depuis_lancement": 2.56}'::jsonb, '{"2024": 7.68, "2023": 6.45, "2022": -11.2, "2021": 1.8, "2020": 6.74, "2019": 8.09, "2018": -3.48, "2017": 2.45, "2016": 2.04, "2015": 1.62}'::jsonb, 'cibleFonds de revenu fixe 70,00 % Fonds d''actions canadiennes 10,50 % Fonds d''actions étrangères 19,50 %'),
  (55, '817', 'Focus modéré (iA)', 'Fonds Focus', 'Équilibrés mondiaux d''actions', 'iA Gestion mondiale d''actifs', '—Portefeuille clé en main pour les investisseurs qui souhaitent que leur tolérance au risque soit respectée en tout temps. —Pour l''expertise des gestionnaires de portefeuilles sous-jacents, sélectionnés par nos experts.', '—Style : Portefeuille à répartition de l''actif fixe, rééquilibré mensuellement. —Approche multigestion qui offre différents styles de gestion complémentaires. —Portefeuille bien diversifié par catégories d’actifs, régions géographiques et secteurs économiques.', 'Variable', '437,6 million', 'octobre 2002', '{"DDA": 3.09, "3mois": 2.06, "6mois": 3.09, "1an": 9.23, "3ans": 7.92, "5ans": 4.14, "10ans": 2.96, "depuis_lancement": 3.37}'::jsonb, '{"2024": 10.37, "2023": 7.43, "2022": -10.82, "2021": 4.53, "2020": 7.14, "2019": 9.71, "2018": -4.79, "2017": 3.39, "2016": 3.32, "2015": 1.64}'::jsonb, 'cibleFonds de revenu fixe 55,00 % Fonds d''actions canadiennes 15,25 % Fonds d''actions étrangères 29,75 %'),
  (56, '818', 'Focus équilibré (iA)', 'Fonds Focus', 'Équilibrés mondiaux d''actions', 'iA Gestion mondiale d''actifs', '—Portefeuille clé en main pour les investisseurs qui souhaitent que leur tolérance au risque soit respectée en tout temps. —Pour l''expertise des gestionnaires de portefeuilles sous-jacents, sélectionnés par nos experts.', '—Style : Portefeuille à répartition de l''actif fixe, rééquilibré mensuellement. —Approche multigestion qui offre différents styles de gestion complémentaires. —Portefeuille bien diversifié par catégories d’actifs, régions géographiques et secteurs économiques.', 'Variable', '681,9 million', 'octobre 2002', '{"DDA": 3.79, "3mois": 2.88, "6mois": 3.79, "1an": 10.88, "3ans": 9.66, "5ans": 6.06, "10ans": 3.86, "depuis_lancement": 4.14}'::jsonb, '{"2024": 13.12, "2023": 8.23, "2022": -10.33, "2021": 7.39, "2020": 7.48, "2019": 11.3, "2018": -6.18, "2017": 4.33, "2016": 4.53, "2015": 1.64}'::jsonb, 'cibleFonds de revenu fixe 40,00 % Fonds d''actions canadiennes 21,00 % Fonds d''actions étrangères 39,00 %'),
  (57, '819', 'Focus croissance (iA)', 'Fonds Focus', 'Équilibrés mondiaux d''actions', 'iA Gestion mondiale d''actifs', '—Portefeuille clé en main pour les investisseurs qui souhaitent que leur tolérance au risque soit respectée en tout temps. —Pour l''expertise des gestionnaires de portefeuilles sous-jacents, sélectionnés par nos experts.', '—Style : Portefeuille à répartition de l''actif fixe, rééquilibré mensuellement. —Approche multigestion qui offre différents styles de gestion complémentaires. —Portefeuille bien diversifié par catégories d’actifs, régions géographiques et secteurs économiques.', 'Variable', '256,4 million', 'octobre 2002', '{"DDA": 4.68, "3mois": 3.75, "6mois": 4.68, "1an": 12.71, "3ans": 11.46, "5ans": 7.8, "10ans": 4.69, "depuis_lancement": 4.84}'::jsonb, '{"2024": 15.73, "2023": 9.07, "2022": -10.23, "2021": 9.92, "2020": 8.01, "2019": 12.83, "2018": -7.59, "2017": 5.27, "2016": 5.74, "2015": 1.64}'::jsonb, 'cibleFonds de revenu fixe 25,00 % Fonds d''actions canadiennes 26,00 % Fonds d''actions étrangères 49,00 %'),
  (58, '820', 'Focus audacieux (iA)', 'Fonds Focus', 'Équilibrés mondiaux d''actions', 'iA Gestion mondiale d''actifs', '—Portefeuille clé en main pour les investisseurs qui souhaitent que leur tolérance au risque soit respectée en tout temps. —Pour l''expertise des gestionnaires de portefeuilles sous-jacents, sélectionnés par nos experts.', '—Style : Portefeuille à répartition de l''actif fixe, rééquilibré mensuellement. —Approche multigestion qui offre différents styles de gestion complémentaires. —Portefeuille bien diversifié par catégories d’actifs, régions géographiques et secteurs économiques.', 'Variable', '85,5 million', 'octobre 2002', '{"DDA": 5.54, "3mois": 4.61, "6mois": 5.54, "1an": 14.57, "3ans": 13.25, "5ans": 9.58, "10ans": 5.55, "depuis_lancement": 5.56}'::jsonb, '{"2024": 18.45, "2023": 9.94, "2022": -10.06, "2021": 12.72, "2020": 8.21, "2019": 14.4, "2018": -8.96, "2017": 6.23, "2016": 7.04, "2015": 1.66}'::jsonb, 'cibleFonds de revenu fixe 10,00 % Fonds d''actions canadiennes 31,50 % Fonds d''actions étrangères 58,50 %'),
  (59, '870', 'Actions canadiennes à petite capitalisation (iA)', 'Fonds d''actions canadiennes', 'Actions canadiennes à petite et moyenne capitalisation', 'iA Gestion mondiale d''actifs', '—Pour les investisseurs qui cherchent à investir dans des entreprises canadiennes plus petites et moins connues qui en sont aux premiers stades de leur croissance. —Est à l''aise avec une plus grande volatilité des rendements.', '—Style : Croissance à un prix raisonnable —Investit principalement dans des titres de sociétés canadiennes à petite et moyenne capitalisation. —Peut investir jusqu''à 30 % de l''actif du fonds en titres étrangers, dont la devise sera couverte.', 'Sans couverture', '189,9 million', 'janvier 2014', '{"DDA": 10.36, "3mois": 11.61, "6mois": 10.36, "1an": 18.81}'::jsonb, '{"2024": 20.0}'::jsonb, '30,18 % Matériaux 20,66 % Énergie 12,76 % Industrie 8,20 % Immobilier 5,70 % Biens de consommation de base 4,40 % Technologies de l''information 4,14 % Finance 3,49 % Consommation discrétionnaire 2,86 % Services aux collectivités 1,99 % Santé'),
  (60, '876', 'Indiciel mondial tous pays (BlackRock)', 'Fonds d''actions américaines et internationales', 'Actions mondiales', 'BlackRock', '—Le Fonds vise à reproduire le rendement de l''indice MSCI Monde tous pays Ex-Canada. —Offre une exposition passive aux actions mondiales.', '—BlackRock utilise une approche indicielle pour gérer le Fonds. —Fonds investi dans un portefeuille largement diversifié de titres de compagnies situées à travers le monde, y compris dans les pays émergents.', 'Sans couverture', '245,0 million', 'juillet 2012', '{"DDA": 3.14, "3mois": 4.92, "6mois": 3.14, "1an": 12.79, "3ans": 16.59, "5ans": 10.57, "10ans": 8.08}'::jsonb, '{"2024": 24.93, "2023": 16.02, "2022": -14.84, "2021": 14.42, "2020": 9.69, "2019": 17.04, "2018": -3.51}'::jsonb, NULL),
  (61, '893', 'Revenu fixe mondial (PIMCO)', 'Fonds de revenu', 'Revenu fixe multisectorielle', 'PIMCO', '—Le Fonds vise à maximiser le revenu courant et la croissance modérée du capital à long terme en investissant principalement dans un portefeuille diversifié de titres à revenu fixe qui ne sont pas libellés en dollars canadiens. —PIMCO est une firme réputée à travers le monde pour sa philosophie novatrice, son expertise reconnue, ses nombreuses ressources et ses gestionnaires chevronnés.', '—Approche active multisectorielle regroupant les meilleures idées de PIMCO pour générer du revenu, peu importe la conjoncture, tout en recherchant des sources de revenu multiples à l’échelle internationale, avec un accent sur les titres de haute qualité. —Jusqu’à 50 % de l’actif total du Fonds peut être investi dans des titres à rendement élevé et jusqu’à 20 % dans des titres et des instruments liés à l’économie des marchés émergents. —La durée moyenne du portefeuille du Fonds varie habituellement entre zéro et huit ans.', 'Couverture active', '1 106,9 million', 'mars 2013', '{"DDA": 3.41, "3mois": 1.1, "6mois": 3.41, "1an": 5.62, "3ans": 4.41, "5ans": 1.79, "10ans": 1.84, "depuis_lancement": 1.92}'::jsonb, '{"2024": 3.11, "2023": 5.87, "2022": -8.27, "2021": -0.27, "2020": 2.3, "2019": 5.09, "2018": -1.24, "2017": 4.96, "2016": 5.7, "2015": 1.08}'::jsonb, NULL),
  (62, '913', 'Indexia prudent (iA)', 'Fonds Indexia', 'Équilibré mondial à revenu fixe', 'iA Gestion mondiale d''actifs', '—Exposition au marché mondial par l''entremise d''un portefeuille diversifié de fonds indiciels. —Bénéficier d’une solution clé en main ou complémentaire dont les frais de gestion sont peu élevés', '—Portefeuille de fonds indiciels qui offre une diversification au moyen d’investissements faits dans différentes classes d’actif, telles que les titres à revenu fixe et les actions à travers le monde. —Répartition de l’actif fixe (gestion passive).', 's.o.', '216,6 million', 'décembre 2017', '{"DDA": 2.46, "3mois": 1.01, "6mois": 2.46, "1an": 7.91, "3ans": 6.26, "5ans": 1.84, "10ans": 2.5}'::jsonb, '{"2024": 7.34, "2023": 7.33, "2022": -12.53, "2021": 1.97, "2020": 7.25, "2019": 8.13, "2018": -1.57, "2017": 3.87}'::jsonb, NULL),
  (63, '914', 'Indexia modéré (iA)', 'Fonds Indexia', 'Équilibrés mondiaux neutres', 'iA Gestion mondiale d''actifs', '—Exposition au marché mondial par l''entremise d''un portefeuille diversifié de fonds indiciels. —Bénéficier d’une solution clé en main ou complémentaire dont les frais de gestion sont peu élevés', '—Portefeuille de fonds indiciels qui offre une diversification au moyen d’investissements faits dans différentes classes d’actif, telles que les titres à revenu fixe et les actions à travers le monde. —Répartition de l’actif fixe (gestion passive).', 's.o.', '213,1 million', 'décembre 2017', '{"DDA": 3.45, "3mois": 2.02, "6mois": 3.45, "1an": 9.9, "3ans": 8.28, "5ans": 3.92, "10ans": 3.76}'::jsonb, '{"2024": 10.03, "2023": 8.69, "2022": -12.07, "2021": 5.21, "2020": 7.4, "2019": 10.16, "2018": -2.51, "2017": 5.69}'::jsonb, NULL),
  (64, '915', 'Indexia équilibré (iA)', 'Fonds Indexia', 'Équilibrés mondiaux neutres', 'iA Gestion mondiale d''actifs', '—Exposition au marché mondial par l''entremise d''un portefeuille diversifié de fonds indiciels. —Bénéficier d’une solution clé en main ou complémentaire dont les frais de gestion sont peu élevés', '—Portefeuille de fonds indiciels qui offre une diversification au moyen d’investissements faits dans différentes classes d’actif, telles que les titres à revenu fixe et les actions à travers le monde. —Répartition de l’actif fixe (gestion passive).', 's.o.', '448,9 million', 'décembre 2017', '{"DDA": 4.42, "3mois": 3.04, "6mois": 4.42, "1an": 11.82, "3ans": 10.27, "5ans": 6.0, "10ans": 4.99}'::jsonb, '{"2024": 12.71, "2023": 10.01, "2022": -11.67, "2021": 8.53, "2020": 7.52, "2019": 12.16, "2018": -3.2, "2017": 7.37}'::jsonb, NULL),
  (65, '916', 'Indexia croissance (iA)', 'Fonds Indexia', 'Équilibrés mondiaux d''actions', 'iA Gestion mondiale d''actifs', '—Exposition au marché mondial par l''entremise d''un portefeuille diversifié de fonds indiciels. —Bénéficier d’une solution clé en main ou complémentaire dont les frais de gestion sont peu élevés', '—Portefeuille de fonds indiciels qui offre une diversification au moyen d’investissements faits dans différentes classes d’actif, telles que les titres à revenu fixe et les actions à travers le monde. —Répartition de l’actif fixe (gestion passive).', 's.o.', '242,0 million', 'décembre 2017', '{"DDA": 5.4, "3mois": 4.09, "6mois": 5.4, "1an": 13.81, "3ans": 12.31, "5ans": 8.12, "10ans": 6.25}'::jsonb, '{"2024": 15.51, "2023": 11.32, "2022": -11.25, "2021": 11.93, "2020": 7.83, "2019": 14.1, "2018": -3.99, "2017": 9.17}'::jsonb, NULL),
  (66, '917', 'Indexia audacieux (iA)', 'Fonds Indexia', 'Actions mondiales', 'iA Gestion mondiale d''actifs', '—Exposition au marché mondial par l''entremise d''un portefeuille diversifié de fonds indiciels. —Bénéficier d’une solution clé en main ou complémentaire dont les frais de gestion sont peu élevés', '—Portefeuille de fonds indiciels qui offre une diversification au moyen d’investissements faits dans différentes classes d’actif, telles que les titres à revenu fixe et les actions à travers le monde. —Répartition de l’actif fixe (gestion passive).', 's.o.', '130,0 million', 'décembre 2017', '{"DDA": 6.37, "3mois": 5.1, "6mois": 6.37, "1an": 15.78, "3ans": 14.33, "5ans": 10.17, "10ans": 7.43}'::jsonb, '{"2024": 18.33, "2023": 12.64, "2022": -11.03, "2021": 15.44, "2020": 7.4, "2019": 16.23, "2018": -4.32, "2017": 10.52}'::jsonb, NULL),
  (67, '920', 'Fidelity Revenu mensuel mondial', 'Fonds diversifiés', 'Équilibré canadien neutre', 'Fidelity Investments', '—Solution mondiale diversifiée et clé en main offrant une exposition aux actions et aux titres à revenu fixe. —Combinaison unique de classes d’actifs qui tendent à présenter une corrélation faible ou négative entre elles et auxquelles un particulier pourrait difficilement accéder.', '—La répartition cible du Fonds correspond à 50 % en actions mondiales et 50 % en titres à revenu fixe, mais le Fonds peut s''en écarter dans une proportion de ±20 %. —Analyse des rendements à court et à long termes des marchés pour cibler les opportunités de diversification dans d''autres régions ou classes d''actifs.', 'Partiellement sans couverture', '503,8 million', 'décembre 2017', '{"DDA": 3.42, "3mois": 0.68, "6mois": 3.42, "1an": 11.77, "3ans": 9.63, "5ans": 5.0, "10ans": 4.64}'::jsonb, '{"2024": 14.62, "2023": 5.81, "2022": -10.75, "2021": 6.48, "2020": 6.44, "2019": 11.04, "2018": -0.45, "2017": 4.25}'::jsonb, ''),
  (68, '921', 'Fidelity Actions mondiales - Concentré', 'Fonds d''actions américaines et internationales', 'Actions mondiales', 'Fidelity Investments', '—Un portefeuille concentré constitué des meilleures idées de placement du gestionnaire, situées n''importe où dans le monde. —Privilégie les sociétés de qualité que le gestionnaire estime être raisonnablement évaluées et qui sont susceptibles d’afficher une croissance prévisible et durable de leurs bénéfices. —Portefeuille diversifié parmi plusieurs secteurs du marché mondial.', '—Style : Qualité à un prix raisonnable (QUARP) —Approche à long terme à contre-courant. —Portefeuille concentré jumelé à des contraintes d’investissement larges permettant de tirer profit de titres pour lesquels le gestionnaire a la plus forte conviction.', 'Sans couverture', '384,6 million', 'décembre 2017', '{"DDA": 14.09, "3mois": 6.58, "6mois": 14.09, "1an": 19.14, "3ans": 18.01, "5ans": 12.5, "10ans": 8.71}'::jsonb, '{"2024": 7.55, "2023": 19.79, "2022": -11.47, "2021": 11.0, "2020": 12.42, "2019": 22.99, "2018": -11.32, "2017": 15.93}'::jsonb, NULL)
