-- =====================================================================
-- Import Supabase — Fonds iA + Profils d'investisseur
-- Généré depuis les fiches de fonds iA (rendements au 30 juin 2025)
-- À exécuter dans Supabase : SQL Editor > New query > Run
-- =====================================================================

-- ---------- Table des fonds ----------
create table if not exists public.fonds (
  id                 bigint primary key,
  code               text unique not null,
  nom                text not null,
  categorie_produit  text,
  categorie_cifsc    text,
  gestionnaire       text,
  pourquoi           text,
  style              text,
  couverture_devises text,
  actif_net          text,
  date_creation      text,
  rendements_composes jsonb,
  rendements_annuels  jsonb,
  composition_actif   text,
  cree_le            timestamptz default now()
);

-- Lecture réservée aux utilisateurs authentifiés (clients connectés)
alter table public.fonds enable row level security;
drop policy if exists "fonds lisibles par utilisateurs authentifies" on public.fonds;
create policy "fonds lisibles par utilisateurs authentifies"
  on public.fonds for select
  to authenticated
  using (true);

on conflict (code) do nothing;


-- ---------- Table des profils d'investisseur ----------
create table if not exists public.profils_allocation (
  profil          text primary key,
  ordre           int,
  pointage_min    int,
  pointage_max    int,
  description      text,
  cible_revenu    int,
  cible_actions   int,
  fourchette_revenu_min int,
  fourchette_revenu_max int,
  fourchette_actions_min int,
  fourchette_actions_max int,
  fonds_focus     text,
  fonds_indexia   text
);

alter table public.profils_allocation enable row level security;
drop policy if exists "profils lisibles par utilisateurs authentifies" on public.profils_allocation;
create policy "profils lisibles par utilisateurs authentifies"
  on public.profils_allocation for select to authenticated using (true);

   fourchette_revenu_min, fourchette_revenu_max, fourchette_actions_min, fourchette_actions_max, fonds_focus, fonds_indexia)
